package shop.ultimatesmp.crates;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
import java.util.*;import java.util.concurrent.atomic.*;import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.event.inventory.*;import org.bukkit.event.player.*;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.plugin.java.JavaPlugin;import org.bukkit.scheduler.*;import org.mockito.*;
class CrateRevealTest {
 static class Fixture implements AutoCloseable{
  final Player p=mock(Player.class);final JavaPlugin plugin=mock(JavaPlugin.class);final BukkitScheduler scheduler=mock(BukkitScheduler.class);final BukkitTask task=mock(BukkitTask.class);
  final AtomicReference<Runnable> tick=new AtomicReference<>();final AtomicReference<Inventory> ui=new AtomicReference<>();final AtomicBoolean ready=new AtomicBoolean(true);final AtomicInteger deliveries=new AtomicInteger(),notices=new AtomicInteger();
  final ItemStack prize=mock(ItemStack.class);final InventoryView view=mock(InventoryView.class);final MockedStatic<Bukkit> bukkit;final MockedConstruction<ItemStack> stacks;final CrateReveal reveal;final Crate crate;
  Fixture(boolean success){
   when(p.getUniqueId()).thenReturn(UUID.randomUUID());when(p.isOnline()).thenReturn(true);when(p.getOpenInventory()).thenReturn(view);when(view.getTopInventory()).thenAnswer(c->ui.get());
   when(scheduler.runTaskTimer(eq(plugin),any(Runnable.class),eq(1L),eq(2L))).thenAnswer(c->{tick.set(c.getArgument(1));return task;});
   when(prize.clone()).thenReturn(prize);when(prize.getType()).thenReturn(Material.DIAMOND);when(prize.getAmount()).thenReturn(1);when(prize.getMaxStackSize()).thenReturn(64);when(prize.getItemMeta()).thenReturn(mock(ItemMeta.class));
   crate=new Crate("common","Common",1,List.of(new Crate.Reward(prize,1)));
   bukkit=mockStatic(Bukkit.class);stacks=mockConstruction(ItemStack.class,(stack,context)->{when(stack.getItemMeta()).thenReturn(mock(ItemMeta.class));when(stack.getType()).thenReturn((Material)context.arguments().get(0));});
   bukkit.when(Bukkit::getScheduler).thenReturn(scheduler);bukkit.when(()->Bukkit.createInventory(any(InventoryHolder.class),eq(27),anyString())).thenAnswer(c->{Inventory inv=mock(Inventory.class);Map<Integer,ItemStack> slots=new HashMap<>();when(inv.getHolder()).thenReturn(c.getArgument(0));doAnswer(call->{slots.put(call.getArgument(0),call.getArgument(1));return null;}).when(inv).setItem(anyInt(),any());when(inv.getItem(anyInt())).thenAnswer(call->slots.get(call.getArgument(0)));ui.set(inv);return inv;});
   reveal=new CrateReveal(plugin,player->ready.get(),3,player->{});reveal.start(p,crate,prize,()->{deliveries.incrementAndGet();return success;},notices::incrementAndGet);
  }
  void ticks(int n){for(int i=0;i<n;i++)tick.get().run();}
  void closeGui(){var event=mock(InventoryCloseEvent.class);when(event.getPlayer()).thenReturn(p);when(event.getInventory()).thenReturn(ui.get());reveal.close(event);}
  public void close(){stacks.close();bukkit.close();}
 }
 @Test void rewardIsNotDeliveredUntilAllThirtySpinFramesFinish(){try(var f=new Fixture(true)){assertEquals(0,f.deliveries.get());f.ticks(30);assertEquals(0,f.deliveries.get());assertEquals(0,f.notices.get());f.ticks(1);assertEquals(1,f.deliveries.get());assertEquals(1,f.notices.get());assertSame(f.prize,f.ui.get().getItem(13));f.ticks(20);f.closeGui();f.reveal.shutdown();assertEquals(1,f.deliveries.get());assertEquals(1,f.notices.get());}}
 @Test void closingEarlyContinuesTheSpinWithoutDeliveringEarly(){try(var f=new Fixture(true)){f.ticks(5);f.closeGui();assertEquals(0,f.deliveries.get());assertTrue(f.reveal.active(f.p.getUniqueId()));verify(f.task,never()).cancel();f.ticks(25);assertEquals(0,f.deliveries.get());f.ticks(1);assertEquals(1,f.deliveries.get());assertEquals(1,f.notices.get());assertFalse(f.reveal.active(f.p.getUniqueId()));f.ticks(10);assertEquals(1,f.deliveries.get());}}
 @Test void disconnectDoesNotConsumeAKeyOrDeliverReward(){try(var f=new Fixture(true)){f.ticks(5);var event=mock(PlayerQuitEvent.class);when(event.getPlayer()).thenReturn(f.p);f.reveal.quit(event);f.ticks(40);assertEquals(0,f.deliveries.get());assertEquals(0,f.notices.get());assertFalse(f.reveal.active(f.p.getUniqueId()));}}
 @Test void deadPlayerDoesNotReceiveAnInFlightReward(){try(var f=new Fixture(true)){f.ticks(5);when(f.p.isDead()).thenReturn(true);f.ticks(40);assertEquals(0,f.deliveries.get());assertEquals(0,f.notices.get());assertFalse(f.reveal.active(f.p.getUniqueId()));}}
 @Test void shutdownDoesNotFinishAnIncompleteSpin(){try(var f=new Fixture(true)){f.ticks(5);f.reveal.shutdown();f.ticks(40);assertEquals(0,f.deliveries.get());assertEquals(0,f.notices.get());assertFalse(f.reveal.active(f.p.getUniqueId()));}}
 @Test void networkFenceOrWorldChangeCancelsWithoutDelivering(){try(var f=new Fixture(true)){f.ticks(4);f.ready.set(false);f.ticks(40);assertEquals(0,f.deliveries.get());assertEquals(0,f.notices.get());}try(var f=new Fixture(true)){f.ticks(4);var event=mock(PlayerChangedWorldEvent.class);when(event.getPlayer()).thenReturn(f.p);f.reveal.changedWorld(event);f.ticks(40);assertEquals(0,f.deliveries.get());}}
 @Test void failedKeyOrSpaceValidationIsNotAnnouncedAsAWinAndNeverRetried(){try(var f=new Fixture(false)){f.ticks(50);assertEquals(1,f.deliveries.get());assertEquals(0,f.notices.get());assertEquals(Material.BARRIER,f.ui.get().getItem(13).getType());f.closeGui();f.reveal.shutdown();assertEquals(1,f.deliveries.get());}}
 @Test void displayItemsCannotBeTakenByAnyInventoryInteraction(){try(var f=new Fixture(true)){f.ticks(31);for(int slot:new int[]{-999,13,30}){var click=mock(InventoryClickEvent.class);when(click.getView()).thenReturn(f.view);when(click.getRawSlot()).thenReturn(slot);f.reveal.click(click);verify(click).setCancelled(true);}var drag=mock(InventoryDragEvent.class);when(drag.getView()).thenReturn(f.view);f.reveal.drag(drag);verify(drag).setCancelled(true);verify(f.p,never()).getInventory();}}
}
